/**
 * QQS-Pro v3 UI — bitmap font / image types.
 * Data is generated by qqs_tools/gen_assets.py into qqs_assets.cpp.
 */
#pragma once

#include <stdint.h>

// One glyph. Bitmap is 2 bits per pixel, MSB first, rows padded to whole bytes.
typedef struct __attribute__((__packed__)) {
  uint16_t cp;        // Unicode code point (BMP only)
  uint8_t  w, h;      // bitmap size
  int8_t   xoff;      // left bearing
  uint8_t  ty;        // top of bitmap, measured from the top of the text line
  uint8_t  adv;       // pen advance
  uint16_t off;       // offset into the font's data blob
} qqs_glyph_t;

typedef struct {
  uint8_t height;               // line height in pixels
  uint16_t count;               // number of glyphs, sorted by cp
  const qqs_glyph_t *glyphs;
  const uint8_t *data;
} qqs_font_t;

// Fixed-size icon / picture. bpp is 1, 2 or 4, same packing as glyphs (MSB first, rows padded).
typedef struct {
  uint8_t w, h, bpp;
  const uint8_t *data;
} qqs_bitmap_t;

// Look up a glyph (binary search). Returns nullptr if the font lacks it.
const qqs_glyph_t *qqs_find_glyph(const qqs_font_t *font, uint16_t cp);

// Decode one UTF-8 code point and advance the pointer. Returns 0 at end of string.
uint16_t qqs_utf8_next(const uint8_t *&s);

// Width in pixels of a UTF-8 string in the given font.
uint16_t qqs_text_width(const qqs_font_t *font, const char *s);
